-- ═══════════════════════════════════════════════════════════════════════════
--  0156 — Khalidiyah's forms, the option lists: one ref_khld_* table per list
--
--  GENERATED by supabase/khalidiyah/gen_schema.py from workbook.py (the one
--  reading of Khaldia_2_reviewed.xlsx) and catalogue.py. Do not edit; edit
--  the catalogue and regenerate. This file creates all 39 tables and seeds
--  the first 20; 0157 seeds the rest and checks all of them.
--
--  39 lists, 196 options, both labels verbatim from the 'Forms needed' sheet
--  in the sheet's order. model.py holds every option to the option cell of
--  every field that reads it, both ways: an option the sheet does not have
--  fails the build, and so does text in a cell no option accounts for.
--  Three fields have no option cell of their own and read a list by the
--  reviewer's note: F060 (Yes / No, a boolean), F061 (the nationality list
--  "as in other forms") and F148 ("options = FORM-12 <F064> list").
--
--  Same shape as every ref_ table (0002, 0122, 0141): code, label_en,
--  label_ar, sort_order, is_active, allows_free_text, the standard block and
--  triggers, read by everyone signed in, written by a coordinator. A list the
--  sheets repeat on several forms, English and Arabic alike, exists once
--  (sex, nationality, disability, id_type, product_type, event_status ...).
--  allows_free_text is true for 12 options, every "Other": the record's
--  <field>_other column, or a junction row's option_other, must say what it
--  was (the "Other (please specify)" convention, OQ-53).
--
--  Yes / No questions are boolean columns and the 1-5 scales integer
--  columns, both labelled from the sheet in the locale, not lists.
-- ═══════════════════════════════════════════════════════════════════════════

do $outer$
declare t text;
begin
  foreach t in array array[
    'ref_khld_partner_type',
    'ref_khld_partner_category',
    'ref_khld_attempt_case',
    'ref_khld_attempt_evaluation',
    'ref_khld_meeting_type',
    'ref_khld_sex',
    'ref_khld_contribution_type',
    'ref_khld_activity_supported',
    'ref_khld_milestone',
    'ref_khld_components_a1',
    'ref_khld_components_b1',
    'ref_khld_components_e1',
    'ref_khld_components_f1',
    'ref_khld_milestone_status',
    'ref_khld_facility_type',
    'ref_khld_campaign_activity_type',
    'ref_khld_event_status',
    'ref_khld_activity_type',
    'ref_khld_target_audience',
    'ref_khld_organiser',
    'ref_khld_nationality',
    'ref_khld_counting_method',
    'ref_khld_observed_interaction',
    'ref_khld_survey_age_group',
    'ref_khld_disability',
    'ref_khld_organisation_type',
    'ref_khld_committee_role',
    'ref_khld_id_type',
    'ref_khld_situation',
    'ref_khld_volunteer_interest',
    'ref_khld_weekday',
    'ref_khld_time_of_day',
    'ref_khld_affiliation',
    'ref_khld_session_topic',
    'ref_khld_working_status',
    'ref_khld_product_type',
    'ref_khld_support_type',
    'ref_khld_support_provider',
    'ref_khld_market_occasion'
  ] loop
    execute format($f$
      create table public.%I (
        id               uuid primary key default gen_random_uuid(),
        code             text not null unique,
        label_en         text not null,
        label_ar         text not null,
        sort_order       int  not null default 0,
        is_active        boolean not null default true,
        allows_free_text boolean not null default false,
        created_at       timestamptz not null default now(),
        updated_at       timestamptz not null default now(),
        created_by       uuid references auth.users(id),
        deleted_at       timestamptz
      )$f$, t);
    execute format('create index %1$s_created_by_idx on public.%1$I (created_by)', t);
    perform public.attach_standard_triggers(t);
    execute format('alter table public.%I enable row level security', t);
    execute format($f$create policy ref_read on public.%I
      for select to authenticated using (true)$f$, t);
    execute format($f$create policy ref_write on public.%I
      for all to authenticated
      using (public.is_coordinator())
      with check (public.is_coordinator())$f$, t);
  end loop;
end $outer$;

